-- =========================================================
-- 序光計畫：☢️ 末世：🏝️ 星露島料理搬進末世
-- 要先執行「2026-10-30_末世_農場.sql」（和它之前的末世檔）。可以重複執行。
--
--   星露島的料理（跟末世重複的除外）加進食物櫃，分成家常菜、拿手菜、招牌菜、傳說料理 4 類
--   這些料理只能在末世廚房自己做（搜刮不會撿到）
--   用到、但末世還沒有的作物也一起加進末世農場；蛋、奶、肉等種不出來的食材改用「食物」代替
--   這個檔會覆蓋 doom_food_cat、doom_farm_cat、doom_pantry_roll，之後不要再單獨重跑前面的美食／異能／農場檔（要重跑的話，最後再跑一次這個檔）
-- =========================================================

create or replace function public.doom_food_cat()
returns jsonb language sql immutable
as $function$
select $json${"cats":[{"id":"staple","name":"主食","emoji":"🍚","zones":["market","night_market","subway"]},{"id":"can","name":"罐頭","emoji":"🥫","zones":["bunker","military","market"]},{"id":"instant","name":"即食","emoji":"🍜","zones":["subway","military","street"]},{"id":"bakery","name":"麵包烘焙","emoji":"🥐","zones":["market","street","library"]},{"id":"sweet","name":"零食甜點","emoji":"🍰","zones":["night_market","market","library"]},{"id":"fruit","name":"水果","emoji":"🍎","zones":["rooftop","market","waterworks"]},{"id":"meat","name":"熟食肉類","emoji":"🍗","zones":["night_market","military","hardware"]},{"id":"drink","name":"飲料","emoji":"🥤","zones":["market","waterworks","street"]},{"id":"hot","name":"熱飲","emoji":"☕","zones":["library","hospital","observatory"]},{"id":"rare","name":"珍品","emoji":"🌟","zones":["observatory","bunker","rooftop"]},{"id":"med","name":"藥品","emoji":"💊","zones":["hospital","bunker","military"]},{"id":"home","name":"家常菜","emoji":"🏠","zones":[]},{"id":"skill","name":"拿手菜","emoji":"👨‍🍳","zones":[]},{"id":"sig","name":"招牌菜","emoji":"⭐","zones":[]},{"id":"legend","name":"傳說料理","emoji":"👑","zones":[]}],"effects":{"c":{"morale":3,"hp":0,"luck":0},"r":{"morale":5,"hp":3,"luck":1},"l":{"morale":8,"hp":5,"luck":3},"x":{"morale":12,"hp":8,"luck":5},"s":{"morale":18,"hp":12,"luck":8}},"items":[{"id":"onigiri","c":"staple","k":"food","t":"c","name":"鮭魚飯糰","emoji":"🍙","text":"包裝有點皺，裡面還是很香。"},{"id":"friedrice","c":"staple","k":"food","t":"c","name":"蛋炒飯","emoji":"🍳","text":"粒粒分明，吃得到鍋氣。"},{"id":"potsticker","c":"staple","k":"food","t":"c","name":"煎餃","emoji":"🥟","text":"底部煎得酥脆。"},{"id":"lurou","c":"staple","k":"food","t":"r","name":"滷肉飯","emoji":"🍚","text":"台灣的味道，吃了會想家。"},{"id":"curry","c":"staple","k":"food","t":"r","name":"咖哩飯","emoji":"🍛","text":"辣得剛剛好。"},{"id":"beefnoodle","c":"staple","k":"food","t":"r","name":"牛肉麵","emoji":"🍜","text":"湯頭熬了很久。"},{"id":"ramen","c":"staple","k":"food","t":"l","name":"豚骨拉麵","emoji":"🍥","text":"濃郁到喝完整碗湯。"},{"id":"sushi","c":"staple","k":"food","t":"x","name":"綜合壽司","emoji":"🍣","text":"末世裡還能吃到生魚片？"},{"id":"corned","c":"can","k":"food","t":"c","name":"鹹牛肉罐","emoji":"🥫","text":"鹹，但很下飯。"},{"id":"sardine","c":"can","k":"food","t":"c","name":"沙丁魚罐","emoji":"🐟","text":"整整齊齊排好的小魚。"},{"id":"beans","c":"can","k":"food","t":"c","name":"茄汁焗豆","emoji":"🫘","text":"甜甜鹹鹹。"},{"id":"cornsoup","c":"can","k":"food","t":"c","name":"玉米濃湯罐","emoji":"🌽","text":"加熱一下就暖起來。"},{"id":"currycan","c":"can","k":"food","t":"r","name":"咖哩雞罐","emoji":"🍲","text":"配什麼都好吃。"},{"id":"crabcan","c":"can","k":"food","t":"l","name":"蟹肉罐","emoji":"🦀","text":"高級罐頭，捨不得吃。"},{"id":"cupnoodle","c":"instant","k":"food","t":"c","name":"杯麵","emoji":"🍜","text":"三分鐘的幸福。"},{"id":"spicynoodle","c":"instant","k":"food","t":"c","name":"辣味泡麵","emoji":"🌶️","text":"辣到流汗，但停不下來。"},{"id":"porridge","c":"instant","k":"food","t":"c","name":"即食粥","emoji":"🥣","text":"生病的時候最需要它。"},{"id":"hotpot","c":"instant","k":"food","t":"r","name":"自熱火鍋","emoji":"🫕","text":"倒水就會自己冒煙。"},{"id":"mre","c":"instant","k":"food","t":"r","name":"軍用即食餐","emoji":"🎖️","text":"熱量很高，夠撐一整天。"},{"id":"hotbento","c":"instant","k":"food","t":"l","name":"自熱便當","emoji":"🍱","text":"有飯有菜有肉。"},{"id":"toast","c":"bakery","k":"food","t":"c","name":"厚片吐司","emoji":"🍞","text":"塗上奶油剛剛好。"},{"id":"bagel","c":"bakery","k":"food","t":"c","name":"貝果","emoji":"🥯","text":"很有嚼勁。"},{"id":"croissant","c":"bakery","k":"food","t":"r","name":"可頌","emoji":"🥐","text":"一層一層酥到掉屑。"},{"id":"donut","c":"bakery","k":"food","t":"r","name":"甜甜圈","emoji":"🍩","text":"糖霜還是粉紅色的。"},{"id":"pizza","c":"bakery","k":"food","t":"l","name":"披薩","emoji":"🍕","text":"起司拉得好長。"},{"id":"cheesecake","c":"bakery","k":"food","t":"x","name":"起司蛋糕","emoji":"🍰","text":"濃郁綿密。"},{"id":"cookie","c":"sweet","k":"food","t":"c","name":"巧克力餅乾","emoji":"🍪","text":"一片接一片。"},{"id":"popcorn","c":"sweet","k":"food","t":"c","name":"爆米花","emoji":"🍿","text":"少了電影院，還是好吃。"},{"id":"gummy","c":"sweet","k":"food","t":"c","name":"小熊軟糖","emoji":"🐻","text":"五顏六色的小熊。"},{"id":"pud